{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C04","C17","C30","C08","C10","C14","C07","C11","C02","C45","C48","C49","C53","C54"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C04","C17","C30","C08","C10","C14","C07","C11","C02","C45","C48","C49","C53","C54"],
  "claims": [
    {
      "claim": "The query is a rigid N-methyl morphinan opioid (hydromorphone-like) with a phenolic C3 and basic amine; closest visible opioid analogues show high intestinal absorption/solubility: codeine F_abs >90% (C53) and high solubility (C49), morphine sulfate solubility 64.5 mg/mL (C48), and dextromethorphan complete/near-complete GI absorption (C45, C54).",
      "card_ids": ["C53","C49","C48","C45","C54"]
    },
    {
      "claim": "Visible opioid systemic-F records are above the 20% threshold: codeine absolute F 80.5% (C04) and relative F 50.2% vs IM (C17, C30), pethidine 0.80±0.15 (C10, C14), pentazocine 0.68–0.70 (C07, C11), meptazinol 27.9% (C08), and naloxegol simulated F 0.90 (C02).",
      "card_ids": ["C04","C17","C30","C10","C14","C07","C11","C08","C02"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F<20% for the query: the only visible low-F record is indacaterol in CD-1 mice (C18), a non-opioid with low applicability, and the L3 ethinylestradiol exposure records (C31–C42) concern a different molecule without IV comparators.",
      "card_ids": ["C18","C31","C32","C33","C34","C35","C36","C37","C38","C39","C40","C41","C42"]
    },
    {
      "claim": "L4 records are absorption/solubility evidence, not direct systemic-F measurements; they strengthen the absorption component but do not replace direct hydromorphone F data. C43 (naringenin dissolution) is not applicable; the rat Fa records (C44, C46, C47, C50–C52) are for a different molecule and are less transferable.",
      "card_ids": ["C43","C44","C45","C46","C47","C48","C49","C50","C51","C52","C53","C54"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C43","C44","C45","C46","C47","C48","C49","C50","C51","C52","C53","C54"]
    }
  ],
  "evidence_gaps": [
    "No direct hydromorphone absolute oral bioavailability record is present in the visible set.",
    "L4 absorption/solubility records are for analogues (codeine, morphine, dextromethorphan), a different rat-dosed molecule (M04/A275), and naringenin, not the query; they are indirect.",
    "Codeine relative bioavailability (C17, C30) is vs intramuscular, not intravenous, so it is not a pure absolute F value.",
    "Several opioid F records are cirrhosis-conditioned; cirrhosis increases F by reducing first-pass metabolism, so healthy-subject transfer is uncertain (e.g., meptazinol 27.9% in cirrhosis is a four-fold increase over controls, C22).",
    "Naloxegol F 0.90 is a PBPK simulation (C02), not a measured clinical absolute F for the query scaffold.",
    "No dose-, formulation-, or prandial-state-matched hydromorphone data are available."
  ],
  "decision_summary": "L4 intestinal absorption/permeability records for close opioid analogues (codeine, morphine, dextromethorphan) show high solubility and near-complete absorption, supporting the absorption component of F. Combined with opioid F records above 20% and no affirmative low-F evidence, the high prediction is strengthened; confidence remains high."
}

